"use client";

import { motion, useReducedMotion } from "framer-motion";
import { useEffect, useState } from "react";

const DEFAULT_WORDS = [
  "Thinking",
  "Pondering",
  "Noodling",
  "Percolating",
  "Finagling",
  "Untangling",
  "Synthesizing",
  "Ruminating",
];

const SCRAMBLE_CHARS = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*";

function scrambleChar() {
  return SCRAMBLE_CHARS[Math.floor(Math.random() * SCRAMBLE_CHARS.length)];
}

function DefaultSpark() {
  return (
    <svg viewBox="0 0 24 24" width="100%" height="100%" fill="currentColor" aria-hidden>
      <path d="M12 1.5 14.4 9.6 22.5 12 14.4 14.4 12 22.5 9.6 14.4 1.5 12 9.6 9.6Z" />
    </svg>
  );
}

export function ThinkingLoader({
  icon,
  words = DEFAULT_WORDS,
  size = 18,
  interval = 2800,
  label = "Loading",
}: {
  icon?: React.ReactNode;
  words?: string[];
  size?: number;
  interval?: number;
  label?: string;
}) {
  const [index, setIndex] = useState(0);
  const [display, setDisplay] = useState(words[0]);
  const shouldReduceMotion = useReducedMotion();

  useEffect(() => {
    const id = setInterval(() => setIndex((i) => (i + 1) % words.length), interval);
    return () => clearInterval(id);
  }, [words, interval]);

  useEffect(() => {
    if (shouldReduceMotion) return;

    const target = words[index];
    let revealed = 0;
    const id = setInterval(() => {
      revealed += 1;
      setDisplay(
        target
          .split("")
          .map((ch, i) => (i < revealed || ch === " " ? ch : scrambleChar()))
          .join(""),
      );
      if (revealed >= target.length) clearInterval(id);
    }, 160);

    return () => clearInterval(id);
  }, [index, words, shouldReduceMotion]);

  return (
    <div
      role="status"
      className="inline-flex items-center gap-2 text-sm font-medium text-slate-600 dark:text-slate-300"
    >
      {/* icon: continuous rotation is the "processing" signal; reduced motion swaps it for a plain opacity breathe */}
      <motion.span
        aria-hidden
        className="relative flex shrink-0 items-center justify-center text-emerald-700 dark:text-emerald-400"
        style={{ width: size, height: size }}
        animate={shouldReduceMotion ? { opacity: [0.55, 1, 0.55] } : { rotate: 360 }}
        transition={
          shouldReduceMotion
            ? { duration: 1.6, repeat: Infinity, ease: "easeInOut" }
            : { duration: 2.6, repeat: Infinity, ease: "linear" }
        }
      >
        {icon ?? <DefaultSpark />}
      </motion.span>

      {/* word + ellipsis are aria-hidden and cycle purely visually; the sr-only label below
          gives assistive tech one static, unchanging accessible name instead of an announcement every interval */}
      <span aria-hidden className="inline-flex items-baseline">
        <span className="relative inline-flex items-baseline overflow-hidden" style={{ height: "1.4em" }}>
          <span className="inline-block">{shouldReduceMotion ? words[index] : display}</span>
        </span>
        <span className="ml-0.5 inline-flex items-center gap-0.5">
          {[0, 1, 2].map((i) => (
            <motion.span
              key={i}
              className="h-1 w-1 rounded-full bg-current"
              animate={shouldReduceMotion ? { opacity: 0.6 } : { opacity: [0.25, 1, 0.25] }}
              transition={{ duration: 1.1, repeat: Infinity, ease: "easeInOut", delay: i * 0.18 }}
            />
          ))}
        </span>
      </span>

      <span className="sr-only">{label}</span>
    </div>
  );
}
